        try (Connection conn = Database.getConnection()) {
            String sql = "SELECT * FROM Contatos"; 
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql);

            while (rs.next()) {
                Contato c = new Contato(
                        rs.getInt("id"),
                        rs.getString("name"),
                        rs.getString("email"),
                        rs.getString("telefone")
                );
                Contatos.add(c);
            }

        } catch (Exception e) {
            e.printStackTrace();
        }

        return Contatos;
    }
